function validate([strs]) {
  if (!Array.isArray(strs) || strs.length < 1 || strs.length > 100) return 'strs needs 1 to 100 strings.';
  const width = strs[0].length;
  if (width < 1 || width > 1000) return 'Each string has 1 to 1000 letters.';
  if (strs.some(s => typeof s !== 'string' || s.length !== width)) return 'All strings must have the same length.';
  if (strs.some(s => !/^[a-z]+$/.test(s))) return 'Strings use lowercase English letters only.';
  return null;
}

