function minDeletionSize(strs) {
  const rows = strs.length;
  const cols = strs[0].length;
  let deleted = 0;

  for (let col = 0; col < cols; col++) {
    for (let row = 1; row < rows; row++) {
      if (strs[row][col] < strs[row - 1][col]) {
        deleted++;
        break;
      }
    }
  }
  return deleted;
}

