function generate(rand, size) {
  const large = size === 'large';
  let n, width;
  if (large) {
    const shape = Math.floor(rand() * 3);
    if (shape === 0) { n = 100; width = 200; }
    else if (shape === 1) { n = 20; width = 1000; }
    else { n = 50; width = 400; }
  } else {
    n = 1 + Math.floor(rand() * 5);
    width = 1 + Math.floor(rand() * 5);
  }
  const letters = large || rand() < 0.4 ? 26 : 3;
  const sortedShare = rand();
  const columns = [];
  for (let j = 0; j < width; j++) {
    const column = Array.from({ length: n }, () => Math.floor(rand() * letters));
    if (rand() < sortedShare) column.sort((a, b) => a - b);
    else if (rand() < 0.2) column.sort((a, b) => b - a);
    columns.push(column);
  }
  const strs = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < width; j++) row += String.fromCharCode(97 + columns[j][i]);
    strs.push(row);
  }
  return [strs];
}
